parameters.jsCode:
const items = $input.all();

const okrs = items.map(item => {
  const props = item.json.properties || {};
  const objective = props['Name']?.title?.map(t => t.plain_text).join('') || 'Untitled';
  const keyResult = props['Key Result']?.rich_text?.map(t => t.plain_text).join('') || '';
  const target = props['Target']?.number || 100;
  const current = props['Current']?.number || 0;
  const owner = props['Owner']?.rich_text?.map(t => t.plain_text).join('') || 'Unassigned';
  const status = props['Status']?.select?.name || 'In Progress';
  const quarter = props['Quarter']?.select?.name || 'Current';

  const progress = target > 0 ? Math.round((current / target) * 100) : 0;
  let health = '🟢';
  if (progress < 30) health = '🔴';
  else if (progress < 60) health = '🟡';

  return {
    pageId: item.json.id,
    objective,
    keyResult,
    target,
    current,
    progress,
    health,
    owner,
    status,
    quarter
  };
});

const avgProgress = okrs.length > 0
  ? Math.round(okrs.reduce((sum, o) => sum + o.progress, 0) / okrs.length)
  : 0;

const onTrack = okrs.filter(o => o.progress >= 60).length;
const atRisk = okrs.filter(o => o.progress >= 30 && o.progress < 60).length;
const offTrack = okrs.filter(o => o.progress < 30).length;

const details = okrs.map(o =>
  `${o.health} *${o.objective}*\n   KR: ${o.keyResult}\n   Progress: ${o.current}/${o.target} (${o.progress}%) | Owner: ${o.owner}`
).join('\n\n');

return [{
  json: {
    avgProgress,
    totalOKRs: okrs.length,
    onTrack,
    atRisk,
    offTrack,
    details,
    okrs,
    week: $now.format('yyyy-WW')
  }
}];

